{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Ensure Google compute firewall ingress does not allow unrestricted http port 80 access",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows unrestricted access to port 80 from any source IP address."
    }
  ],
  "patched_code": "resource "google_compute_firewall" "allow_http_https" {
  name    = "digital-asset-trading-platform-firewall-web"
  network = google_compute_network.digital_asset_trading_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["443", "8080"]
  }
  allow {
    protocol = "tcp"
    ports    = ["80"]
    source_ranges = ["10.0.0.0/16"] # Assuming a private network range, adjust according to your needs
  }
  target_tags   = ["web-server"]
}",
  "fix_summary": "Restrict access to port 80 by specifying a limited source IP range instead of 0.0.0.0/0. For demonstration, a private range 10.0.0.0/16 is used; adjust this according to your organization's IP range."
}
